// 地球の上で: three small facts under 基本情報 on Country and Region pages.
//   現地時刻      — live local time of the capital / seat (one zone per page), with 時差 to Japan;
//   同じ緯度      — a Japanese city (or a capital on another continent) at almost the same latitude;
//   地球の反対側  — Countries whose land lies on the opposite side of the Earth (land to land).
// Data: data/geo-facts.json, generated by scripts/build_geo_facts.py.
(() => {
  'use strict';
  const regionPath = location.pathname.match(/\/countries\/([a-z0-9-]+)\/([a-z0-9-]+)\/?$/);
  const slug = regionPath ? regionPath[2] : document.documentElement.dataset.country;
  if (!slug || !/^[a-z0-9-]+$/.test(slug) || slug === 'japan') return;

  const icon = (name) => `<svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24"><use href="assets/icons/atlas-icons.svg#${name}"></use></svg>`;
  const lat = (value) => `${value < 0 ? '南緯' : '北緯'}${Math.abs(value).toFixed(1)}°`;
  const make = (tag, className, text) => {
    const element = document.createElement(tag);
    if (className) element.className = className;
    if (text !== undefined) element.textContent = text;
    return element;
  };
  const row = (iconName, label, value) => {
    const group = document.createElement('div');
    group.innerHTML = `${icon(iconName)}<dt></dt>`;
    group.querySelector('dt').textContent = label;
    const dd = make('dd');
    dd.append(...value);
    group.append(dd);
    return group;
  };
  const countryLink = (target, text) => {
    const link = make('a', 'geo-facts__link', text);
    link.href = `countries/${target}/`;
    return link;
  };

  function partOfDay(hour) {
    if (hour >= 5 && hour < 10) return '朝';
    if (hour >= 10 && hour < 16) return '昼';
    if (hour >= 16 && hour < 19) return '夕方';
    return '夜';
  }
  function offsetMinutes(zone, date) {
    const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
      timeZone: zone, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric'
    }).formatToParts(date).map((part) => [part.type, part.value]));
    const asUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute);
    return Math.round((asUtc - date.getTime()) / 60000);
  }
  function timeText(zone) {
    const now = new Date();
    const clock = new Intl.DateTimeFormat('ja-JP', { timeZone: zone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(now);
    const hour = Number(clock.split(':')[0]);
    const diff = offsetMinutes(zone, now) - offsetMinutes('Asia/Tokyo', now);
    const hours = Math.abs(diff) / 60;
    const amount = Number.isInteger(hours) ? `${hours}時間` : `${Math.floor(hours)}時間${Math.abs(diff) % 60}分`;
    const relation = diff === 0 ? '日本と同じ' : `日本より${amount}${diff < 0 ? '遅い' : '進んでいる'}`;
    return `${clock}（${partOfDay(hour)}）・${relation}`;
  }

  function mount(entry) {
    if (!entry || document.querySelector('.geo-facts')) return;
    const facts = document.querySelector('#facts') || document.querySelector('.country-facts-strip .fact-list');
    if (!facts) return;
    const list = make('dl', 'fact-list geo-facts');
    list.setAttribute('aria-label', '地球の上で');

    if (entry.tz) {
      const value = make('span', 'geo-facts__time');
      const update = () => { try { value.textContent = timeText(entry.tz); } catch { value.textContent = ''; } };
      update();
      if (value.textContent) {
        window.setInterval(update, 30000);
        const placeName = entry.place?.nameJa ? `${entry.place.nameJa}の` : '';
        list.append(row('clock', '現地時刻', [make('span', 'geo-facts__note', placeName), value]));
      }
    }
    if (entry.latitude && entry.place) {
      const here = `${entry.place.label || ''}${entry.place.nameJa}（${lat(entry.place.lat)}）は、`;
      const there = entry.latitude.kind === 'japan'
        ? [make('span', '', `${entry.latitude.nameJa}（${lat(entry.latitude.lat)}）`)]
        : [make('span', '', `${entry.latitude.nameJa}（`), countryLink(entry.latitude.slug, entry.latitude.countryJa), make('span', '', '）')];
      list.append(row('compass', '同じ緯度', [make('span', '', here), ...there, make('span', '', 'とほぼ同じ緯度')]));
    }
    if (Array.isArray(entry.antipode) && entry.antipode.length) {
      const value = [];
      entry.antipode.forEach((item, index) => {
        if (index) value.push(make('span', '', '・'));
        value.push(countryLink(item.slug, item.nameJa));
      });
      value.push(make('span', 'geo-facts__note', 'の陸地'));
      list.append(row('globe', '地球の反対側', value));
    }
    if (!list.children.length) return;
    list.dataset.count = String(list.children.length);
    facts.after(list);
  }

  const ready = fetch('data/geo-facts.json')
    .then((response) => { if (!response.ok) throw new Error('geo-facts'); return response.json(); })
    .then((data) => data.entries?.[slug]);
  const start = () => ready.then(mount).catch((error) => console.warn('[JOURNEY ATLAS] Geo facts unavailable.', error));
  // Country pages render 基本情報 after their data loads; Region pages are static.
  if (document.querySelector('#facts')?.children.length || (!document.querySelector('#facts') && document.querySelector('.country-facts-strip .fact-list'))) start();
  else window.addEventListener('journeyatlas:countryready', () => requestAnimationFrame(start), { once: true });
})();
